import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder sb = new StringBuilder();
        String line;
        while ((line = br.readLine()) != null) {
            sb.append(line).append(' ');
        }

        String trimmed = sb.toString().trim();
        if (trimmed.isEmpty()) return;
        String[] tokens = trimmed.split("\\s+");
        if (tokens.length < 2) return;

        int k = Integer.parseInt(tokens[0]);
        int n = Integer.parseInt(tokens[1]);

        StringBuilder rest = new StringBuilder();
        for (int i = 2; i < tokens.length; i++) {
            rest.append(tokens[i]);
        }
        String all = rest.toString();

        int endAlpha = Math.min(k, all.length());
        String alphabet = all.substring(0, endAlpha);
        String message = all.substring(endAlpha, Math.min(k + n, all.length()));

        boolean[] present = new boolean[128];
        for (int i = 0; i < alphabet.length(); i++) {
            present[alphabet.charAt(i)] = true;
        }

        boolean ok = true;
        for (int i = 0; i < message.length(); i++) {
            char c = message.charAt(i);
            if (c >= 128 || !present[c]) {
                ok = false;
                break;
            }
        }

        System.out.println(ok ? "S" : "N");
    }
}
